/* Unit test for treefiles path construction and block mapping. */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <limits.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/stat.h>

#include "config.h"
#include "treefiles.h"

/* stubs for cliserv symbols used by treefiles.c */
void nbd_err(const char *s) {
	fprintf(stderr, "FATAL: %s\n", s);
	exit(EXIT_FAILURE);
}

static int failures = 0;

#define CHECK(cond, ...) do { \
	if (!(cond)) { \
		failures++; \
		fprintf(stderr, "FAIL(%d): ", __LINE__); \
		fprintf(stderr, __VA_ARGS__); \
		fprintf(stderr, "\n"); \
	} \
} while (0)

static void path_for(char *out, const char *root, off_t size, off_t pos) {
	off_t ppos;
	strcpy(out, root);
	construct_path(out + strlen(root), PATH_MAX - strlen(root) - 1,
		       size, pos, &ppos);
}

static void test_layout(void) {
	char a[PATH_MAX], b[PATH_MAX];
	off_t ppos;

	/* small export: 4 MiB = 1024 blocks of 4K. All blocks live in
	 * a single TREE directory. */
	off_t size = 4194304;
	strcpy(a, "/r");
	construct_path(a + 2, PATH_MAX - 3, size, 0, &ppos);
	printf("4MiB pos=0       -> /r%s  (ppos=%lld)\n", a + 2, (long long)ppos);
	CHECK(ppos == 0, "ppos should be 0 for block-aligned pos");

	strcpy(b, "/r");
	construct_path(b + 2, PATH_MAX - 3, size, 4096, &ppos);
	printf("4MiB pos=4096    -> /r%s\n", b + 2);
	CHECK(strcmp(a, b) != 0, "different blocks must map to different files");

	/* within-block offset */
	strcpy(b, "/r");
	construct_path(b + 2, PATH_MAX - 3, size, 4096 + 100, &ppos);
	printf("4MiB pos=4196    -> /r%s  (ppos=%lld)\n", b + 2, (long long)ppos);
	CHECK(ppos == 100, "ppos must be the in-block offset");

	/* same block, different in-block offset -> same file */
	char c[PATH_MAX];
	strcpy(c, "/r");
	construct_path(c + 2, PATH_MAX - 3, size, 4096 + 3000, &ppos);
	CHECK(strcmp(b, c) == 0, "same block must map to the same file");

	/* large export needing several TREE levels: 4 GiB */
	off_t big = 4294967296LL;
	char x1[PATH_MAX], x2[PATH_MAX], x3[PATH_MAX];
	strcpy(x1, "/r"); construct_path(x1 + 2, PATH_MAX - 3, big, 0, &ppos);
	strcpy(x2, "/r"); construct_path(x2 + 2, PATH_MAX - 3, big, 4096LL * 1024, &ppos);
	strcpy(x3, "/r"); construct_path(x3 + 2, PATH_MAX - 3, big, 4096LL * 1024 * 1024, &ppos);
	printf("4GiB pos=0       -> /r%s\n", x1 + 2);
	printf("4GiB pos=4MiB    -> /r%s\n", x2 + 2);
	printf("4GiB pos=4GiB/1k -> /r%s\n", x3 + 2);
	CHECK(strcmp(x1, x2) != 0, "big: distinct blocks must differ");
	CHECK(strcmp(x2, x3) != 0, "big: far-apart blocks must differ");

	/* count directory fanout: every path component after /r must be
	 * either TREExxxx or FILExxxx */
	const char *p = x3 + 2;
	while (*p) {
		CHECK(*p == '/', "component must start with /");
		p++;
		CHECK(strncmp(p, "TREE", 4) == 0 || strncmp(p, "FILE", 4) == 0,
		      "component must be TREE*/FILE*, got %.4s", p);
		p += 4;
		/* 4 hex digits */
		for (int i = 0; i < 4; i++) {
			CHECK(isxdigit((unsigned char)*p) != 0, "hex digit expected");
			p++;
		}
	}
}

static void test_open_read_write(void) {
	char root[] = "/tmp/nbd-tree-unit-XXXXXX";
	char *dir = mkdtemp(root);
	CHECK(dir != NULL, "mkdtemp");
	pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
	off_t size = 4194304;

	/* write to block 5, then read it back */
	off_t pos = 5 * 4096;
	int fd = open_treefile(dir, O_RDWR, size, pos, &mu);
	CHECK(fd >= 0, "open_treefile for write");
	char buf[4096];
	memset(buf, 'A', sizeof(buf));
	CHECK(pwrite(fd, buf, 4096, pos % TREEPAGESIZE) == 4096, "pwrite");
	close(fd);

	char rbuf[4096];
	memset(rbuf, 0, sizeof(rbuf));
	fd = open_treefile(dir, O_RDWR, size, pos, &mu);
	CHECK(fd >= 0, "open_treefile for read");
	CHECK(pread(fd, rbuf, 4096, pos % TREEPAGESIZE) == 4096, "pread");
	CHECK(rbuf[0] == 'A' && rbuf[4095] == 'A', "data round-trips");
	close(fd);

	/* a different block reads as zeroes (not written) */
	off_t pos2 = 6 * 4096;
	fd = open_treefile(dir, O_RDWR, size, pos2, &mu);
	CHECK(fd >= 0, "open_treefile for unwritten block (creates zeroed)");
	memset(rbuf, 0xFF, sizeof(rbuf));
	CHECK(pread(fd, rbuf, 4096, 0) == 4096, "pread unwritten block");
	int allzero = 1;
	for (int i = 0; i < 4096; i++) if (rbuf[i] != 0) { allzero = 0; break; }
	CHECK(allzero, "unwritten block must be zero-filled");
	close(fd);

	/* delete_treefile removes the file */
	char before[PATH_MAX], after[PATH_MAX];
	path_for(before, dir, size, pos);
	CHECK(access(before, F_OK) == 0, "block file exists before delete");
	delete_treefile(dir, size, pos);
	path_for(after, dir, size, pos);
	CHECK(access(after, F_OK) != 0, "block file removed after delete");

	pthread_mutex_destroy(&mu);
}

int main(void) {
	test_layout();
	test_open_read_write();
	if (failures) {
		fprintf(stderr, "%d failure(s)\n", failures);
		return 1;
	}
	printf("All treefiles unit tests passed.\n");
	return 0;
}

