	count_assert(strlen(a) > strlen(b));

	/* write a block, read it back */
	memset(buf, 'A', TREEPAGESIZE);
	fd = open_treefile(root, O_RDWR, size, 5 * TREEPAGESIZE, &lock);
	count_assert(fd >= 0);
	count_assert(pwrite(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	count_assert(close(fd) == 0);

	memset(buf, 0, TREEPAGESIZE);
	fd = open_treefile(root, O_RDWR, size, 5 * TREEPAGESIZE + 512, &lock);
	count_assert(fd >= 0);
	count_assert(pread(fd, buf, TREEPAGESIZE - 512, 512) == TREEPAGESIZE - 512);
	count_assert(buf[0] == 'A' && buf[TREEPAGESIZE - 513] == 'A');
	count_assert(close(fd) == 0);

	/* reading an unwritten block gives zeroes */
	fd = open_treefile(root, O_RDONLY, size, 6 * TREEPAGESIZE, &lock);
	count_assert(fd >= 0);
	memset(buf, 0xFF, TREEPAGESIZE);
	count_assert(pread(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	for (int i = 0; i < TREEPAGESIZE; i++)
		count_assert(buf[i] == 0);
	count_assert(close(fd) == 0);

	/* TRIM on a treefiles export deletes the affected block files */
	SERVER srv;
	CLIENT cl;
	struct nbd_request req;

	memset(&srv, 0, sizeof(SERVER));
	srv.exportname = root;
	srv.expected_size = size;
	srv.flags = F_TREEFILES;
	srv.servename = "treefiles";

	memset(&cl, 0, sizeof(CLIENT));
	cl.exportsize = size;
	cl.exportname = root;
	cl.export = NULL;
	cl.server = &srv;
	pthread_mutex_init(&cl.lock, NULL);

	/* block 5 was written above; trim it */
	req.magic = NBD_REQUEST_MAGIC;
	req.type = NBD_CMD_TRIM;
	req.from = 5 * TREEPAGESIZE;
	req.len = TREEPAGESIZE;
	count_assert(exptrim(&req, &cl) == 0);
	path_for(a, root, size, 5 * TREEPAGESIZE);
	count_assert(access(a, F_OK) == -1);

	/* and it reads back as zeroes afterwards */
	fd = open_treefile(root, O_RDONLY, size, 5 * TREEPAGESIZE, &lock);
	count_assert(fd >= 0);
	memset(buf, 0xFF, TREEPAGESIZE);
	count_assert(pread(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	for (int i = 0; i < TREEPAGESIZE; i++)
		count_assert(buf[i] == 0);
	count_assert(close(fd) == 0);

	/* trimming an empty range touches nothing */
	fd = open_treefile(root, O_RDWR, size, 7 * TREEPAGESIZE, &lock);
	count_assert(fd >= 0);
	memset(buf, 'B', TREEPAGESIZE);
	count_assert(pwrite(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	count_assert(close(fd) == 0);
	req.from = 7 * TREEPAGESIZE + 100;
	req.len = 100;
	count_assert(exptrim(&req, &cl) == 0);
	path_for(a, root, size, 7 * TREEPAGESIZE);
	count_assert(access(a, F_OK) == 0);

	return 0;
}

