/*
 * Tree files support: an export is stored as a tree of small block
 * files rather than as one large file. This is useful on filesystems
 * that do not handle large files well (fuse/ftpfs, davfs and other
 * network filesystems).
 *
 * The export lives in a directory named after the exportname. Each
 * directory contains at most TREEDIRSIZE entries; the leaf entries
 * are block files of TREEPAGESIZE bytes, named FILEXXXX. If the
 * export is too large to fit in a single directory, intermediate
 * directories named TREEXXXX are created, nested as deep as needed.
 *
 * Block files are created on demand when the corresponding block is
 * written, and deleted again when the block is trimmed; reading a
 * block for which no file exists yields zeroes.
 */

#include <errno.h>
#include <fcntl.h>
