/**
 * Recursive worker for construct_path. Appends the path components for
 * the block containing position pos, starting at the deepest level.
 *
 * @param name buffer to append the path components to
 * @param lenmax size of the buffer at name
 * @param size size covered by this level of the tree
 * @param pos position in the export
 * @param ppos scratch space; used to pass the index for the next
 * directory level up the recursion
 **/
static void construct_path_rec(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	if(lenmax < 10)
		err("Char buffer overflow. This is likely a bug.");

	if(size < TREEDIRSIZE * TREEPAGESIZE) {
		/* we are done, add the block file name */
		snprintf(name, lenmax, "/FILE%04" PRIX64,
			 (uint64_t)(pos / TREEPAGESIZE) % TREEDIRSIZE);
		*ppos = pos / (TREEPAGESIZE * TREEDIRSIZE);
	} else {
		construct_path_rec(name + 9, lenmax - 9, size / TREEDIRSIZE, pos, ppos);
		char buffer[10];
		snprintf(buffer, sizeof(buffer), "/TREE%04" PRIX64,
			 (uint64_t)(*ppos % TREEDIRSIZE));
		/* copy without the trailing nul; the deeper path
		 * components follow immediately */
		memcpy(name, buffer, 9);
		*ppos /= TREEDIRSIZE;
	}
}

/**
 * Append the tree path components for the block containing position
 * pos to name, which must already contain the path of the tree's root
 * directory. The number of directory levels is derived from the total
 * export size.
 *
 * @param name buffer holding the tree root path; the path of the block
 * file is appended here
 * @param lenmax size of the buffer at name
 * @param size total size of the export
 * @param pos position in the export
 * @param ppos [out] offset of pos within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	construct_path_rec(name, lenmax, size, pos, ppos);
	*ppos = pos % TREEPAGESIZE;
}

/**
 * Create all directories in the given path, like mkdir -p. The last
 * path component is assumed to be a file name and is not created.
 *
 * @param path absolute path to create the directory components of
 **/
void mkdir_path(char *path) {
	char *subpath = path + 1;

	while((subpath = strchr(subpath, '/'))) {
		*subpath = '\0';
		if(mkdir(path, 0700) == -1) {
			if(errno != EEXIST)
				err("Path access error! %m");
		}
		*subpath = '/';
		subpath++;
	}
}

/**
 * Delete the block file containing position pos, if it exists. Used
 * to handle TRIM requests; the block reads back as zeroes afterwards.
 *
 * @param name path of the tree's root directory
 * @param size total size of the export
 * @param pos position in the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char filename[PATH_MAX];
	off_t ppos;

	strncpy(filename, name, PATH_MAX - 1);
	filename[PATH_MAX - 1] = '\0';
	construct_path(filename + strlen(filename),
		       PATH_MAX - strlen(filename) - 1,
		       size, pos, &ppos);

	DEBUG("Deleting treefile: %s\n", filename);

	if(unlink(filename) == -1 && errno != ENOENT)
		DEBUG("Deleting failed: %s\n", strerror(errno));
}

/**
 * Open the block file containing position pos, creating it (and any
 * missing directories) if necessary. If the file does not exist and
 * cannot be created because the export is read-only, an anonymous
 * temporary file full of zeroes is returned instead, so that reading
 * unwritten blocks succeeds.
 *
 * The returned descriptor is opened for a single read or write
 * operation; the caller must close it.
 *
 * @param name path of the tree's root directory
 * @param mode open mode; O_RDWR if the block may be written
 * @param size total size of the export
 * @param pos position in the export
 * @param mutex lock serializing file creation between threads
 * @return a file descriptor, or -1 on failure
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char filename[PATH_MAX];
	off_t ppos;
	int handle;

	strncpy(filename, name, PATH_MAX - 1);
	filename[PATH_MAX - 1] = '\0';
	construct_path(filename + strlen(filename),
		       PATH_MAX - strlen(filename) - 1,
		       size, pos, &ppos);

	DEBUG("Accessing treefile %s (offset %llu of %llu)\n", filename,
	      (unsigned long long)pos, (unsigned long long)size);

	pthread_mutex_lock(mutex);
	handle = open(filename, mode, 0600);
	if(handle < 0 && errno == ENOENT) {
		if(mode & O_RDWR) {
			DEBUG("Creating new treefile %s\n", filename);
			mkdir_path(filename);
			handle = open(filename, O_RDWR | O_CREAT, 0600);
		} else {
			/* Reading an unwritten block on a read-only
			 * export; give back an anonymous file full of
			 * zeroes instead */
			DEBUG("Creating a dummy tempfile for reading\n");
			char tmpname[] = "dummy-XXXXXX";
			mode_t oldmode = umask(077);
			handle = mkstemp(tmpname);
			umask(oldmode);
			if(handle >= 0)
				unlink(tmpname); /* File will stick around whilst FD open */
		}
		if(handle < 0) {
			pthread_mutex_unlock(mutex);
			return -1;
		}
		/* Grow the file to a full block, so that reads and
		 * writes anywhere in the block succeed */
		char nul = '\0';
		if(lseek(handle, TREEPAGESIZE - 1, SEEK_SET) < 0 ||
		   write(handle, &nul, 1) < 1) {
			int saved_errno = errno;
			close(handle);
			errno = saved_errno;
			pthread_mutex_unlock(mutex);
			return -1;
		}
	}
	pthread_mutex_unlock(mutex);
	return handle;
}

